import {
  showErrorMessage,
  showSuccessMessage,
  unreadNotifications,
} from '/static/js/common/notification.prod.js';
import {
  saveImage,
  fadeOutModal,
  fadeInModal,
  loaderScreen,
  fadeOutLoader,
} from '/static/js/common/functions.prod.js';
document.addEventListener('DOMContentLoaded', function () {
  unreadNotifications();
  let e = localStorage.getItem('access') || null;
  ($('.profileHolder').on('click', function () {
    let t = $('.helperHolder');
    t.hasClass('animate__fadeInDown')
      ? t.removeClass('animate__fadeInDown').addClass('animate__fadeOutUp')
      : $.ajax({
          type: 'GET',
          url: 'https://cloud.smartstock.africa/smst_user/',
          headers: { Authorization: `Bearer ${e}` },
          success: function (e) {
            (Object.entries(e).forEach(([e, t]) => {
              $(`#${e}`).empty().append(t);
            }),
              $('.helperHolder')
                .removeClass('animate__fadeOutUp')
                .addClass('animate__fadeInDown'));
          },
        });
  }),
    $('body').on('click', '.addImageHolder', function () {
      $('#imageInput').trigger('click');
    }),
    $('body').on('change', '#imageInput', function (e) {
      loaderScreen(gettext('Loading your Image'));
      const t = e.target.files[0];
      if (!t) return;
      if (t.size > 5242880)
        return (
          showErrorMessage(
            gettext('Image too big'),
            gettext('Kindly choose an image lower than 5MB')
          ),
          void (this.value = '')
        );
      if (!['image/jpeg'].includes(t.type))
        return (
          showErrorMessage(
            gettext('Not an Image'),
            gettext('Only JPG and JPEG images are allowed!')
          ),
          (this.value = ''),
          void fadeOutLoader()
        );
      const o = new Image();
      ((o.src = URL.createObjectURL(t)),
        (o.onload = function () {
          const e = 1280 / o.width,
            t = o.height * e,
            i = document.createElement('canvas'),
            n = i.getContext('2d');
          ((i.width = 1280),
            (i.height = t),
            n.drawImage(o, 0, 0, 1280, t),
            i.toBlob(
              function (e) {
                if (!e)
                  return (
                    showErrorMessage(
                      gettext('Image Processing Failed'),
                      gettext('Could not process image, kindly try again')
                    ),
                    void fadeOutLoader()
                  );
                const t = $('#imageEditPreview');
                t[0].dataset.objectURL &&
                  URL.revokeObjectURL(t[0].dataset.objectURL);
                const o = URL.createObjectURL(e);
                ((t[0].dataset.objectURL = o),
                  (t[0].onload = function () {
                    (t.data('cropper') && t.cropper('destroy'),
                      t.cropper({
                        aspectRatio: 1,
                        viewMode: 3,
                        minCanvasHeight: 100,
                        autoCropArea: 1,
                        zoomable: !1,
                        minCropBoxHeight: 100,
                      }));
                  }),
                  (t[0].src = o),
                  fadeInModal('.imageEdit', '.imageEditHolder'));
              },
              'image/webp',
              0.9
            ));
        }));
    }),
    $('body').on('pointerdown', '#descriptionButton', function (e) {
      e.preventDefault();
    }),
    $('body').on('click', '#descriptionButton', function () {
      const e = $('#productDescriptionInput');
      let t = e.val().trim(),
        o = new Array();
      if (t.length && ((o = JSON.parse(t)), o.length >= 5))
        return void showErrorMessage(
          gettext('Maximum Descriptions'),
          gettext('You have reached your free limit for descriptions.')
        );
      let i = $('.doubleInputHolder').find('input'),
        n = !1;
      i.each(function () {
        if (!$(this).val().trim().length)
          return (
            (n = !0),
            showErrorMessage(
              gettext('Fill Empty Fields'),
              gettext('Kindly fill in the empty fields.')
            ),
            $(this).focus(),
            !1
          );
        n = !1;
      });
      const r = {
        descriptionType: $('#descriptionType').val().trim(),
        descriptionValue: $('#descriptionValue').val().trim(),
      };
      if (n) return;
      let a = $(
          '<div class="productDescription flex animate__animated animate__fadeInUp"></div>'
        ),
        s = $('<div class="prodDesc"></div>'),
        d = $('<div class="descriptionType"></div>').append(r.descriptionType),
        c = $('<div class="descriptionValue"></div>').append(
          r.descriptionValue
        ),
        p = $(
          '\n        <div class="decriptionOptions flex align-center">\n          <div class="editDescriptionButton descriptionOptionButton">\n            <svg width="24px" height="24px" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">\n              <path d="M15.4998 5.49994L18.3282 8.32837M3 20.9997L3.04745 20.6675C3.21536 19.4922 3.29932 18.9045 3.49029 18.3558C3.65975 17.8689 3.89124 17.4059 4.17906 16.9783C4.50341 16.4963 4.92319 16.0765 5.76274 15.237L17.4107 3.58896C18.1918 2.80791 19.4581 2.80791 20.2392 3.58896C21.0202 4.37001 21.0202 5.63634 20.2392 6.41739L8.37744 18.2791C7.61579 19.0408 7.23497 19.4216 6.8012 19.7244C6.41618 19.9932 6.00093 20.2159 5.56398 20.3879C5.07171 20.5817 4.54375 20.6882 3.48793 20.9012L3 20.9997Z" stroke="#000000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>\n            </svg>\n          </div>\n          <div class="deleteDescriptionButton descriptionOptionButton">\n            <svg width="24px" height="24px" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">\n              <path d="M10 12V17" stroke="#000000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>\n              <path d="M14 12V17" stroke="#000000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>\n              <path d="M4 7H20" stroke="#000000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>\n              <path d="M6 10V18C6 19.6569 7.34315 21 9 21H15C16.6569 21 18 19.6569 18 18V10" stroke="#000000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>\n              <path d="M9 5C9 3.89543 9.89543 3 11 3H13C14.1046 3 15 3.89543 15 5V7H9V5Z" stroke="#000000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>\n            </svg>\n          </div>\n        </div>\n      '
        );
      ($('.productDescriptions').append(a.append(s.append(d, c), p)),
        o.push(r),
        e.val(JSON.stringify(o)),
        o.length >= 5 &&
          ($('.doubleInputHolder').find('button').prop('disabled', !0),
          showErrorMessage(
            gettext('Maximum Descriptions Reached'),
            gettext('You have reached your maximum of 5 descriptions.')
          )),
        i.val(''));
    }),
    $('body').on('click', '#cancelEditing', function () {
      fadeOutModal('.imageEdit', '.imageEditHolder');
    }),
    $('body').on('click', '#saveEditing', function () {
      saveImage();
    }),
    $('body').on('click', '.descriptionOptionButton', function () {
      let e = $(this).closest('.productDescription'),
        t = e.index(),
        o = JSON.parse($('#productDescriptionInput').val().trim());
      if ($(this).hasClass('editDescriptionButton')) {
        let e = o[t];
        ($('#descriptionType').val(e.descriptionType),
          $('#descriptionValue').val(e.descriptionValue));
      }
      (o.splice(t, 1),
        $('#productDescriptionInput').val(JSON.stringify(o)),
        e.remove(),
        $(this).hasClass('deleteDescriptionButton') &&
          showErrorMessage(
            gettext('Deleted Description'),
            gettext('You have removed the description')
          ),
        $('#descriptionButton').prop('disabled', !1));
    }),
    $('body').on('click', '#createProductButton', function () {
      let t = $('#imageInput')[0].files[0],
        o = $('#productName').val().trim(),
        i = $('#productDescriptionInput').val().trim(),
        n = new FormData();
      (n.append('product_image', t),
        n.append('product_name', o),
        n.append('product_description', i),
        $.ajax({
          method: 'POST',
          url: 'https://cloud.smartstock.africa/stock_products/',
          headers: { Authorization: `Bearer ${e}` },
          processData: !1,
          contentType: !1,
          data: n,
          success: function (e) {
            showSuccessMessage(
              interpolate(gettext('Product %s Created'), [e.product_name]),
              gettext('The product has been saved and added to stock')
            );
          },
        }));
    }));
});
